(()=>{'use strict';const A=App,E=Engine,t=A.t,e=A.e,b=A.btn,f=A.field;
const check=(name,label,value)=>`<label class="check"><input type="checkbox" name="${name}" ${value?'checked':''}>${label}</label>`;
const errors=()=>'<div class="form-error" role="alert"></div>';
const end=label=>`${errors()}<div class="dialog-actions">${b('close',t('Cancel','取消'))}<button type="submit" class="primary">${label}</button></div>`;
A.lineRow=(x={},quote=false)=>`<tr><td><input data-line="product" aria-label="${t('Product','产品')}" maxlength="200" required value="${e(x.product)}"><div class="item-identifiers"><input data-line="sku" aria-label="${t('SKU','SKU编码')}" placeholder="${t('SKU (optional)','SKU（可选）')}" maxlength="100" value="${e(x.sku)}"><input data-line="specification" aria-label="${t('Specification','规格')}" placeholder="${t('Specification / pack size','规格 / 包装大小')}" maxlength="300" value="${e(x.specification)}"></div></td><td><input data-line="unit" aria-label="${t('Unit','单位')}" maxlength="50" value="${e(x.unit)}"></td><td><input data-line="qty" aria-label="${t('Quantity','数量')}" type="number" min="0.0001" max="1000000" step="0.0001" required value="${e(x.qty??1)}"></td>${quote?`<td><input data-line="price" aria-label="${t('Unit price','单价')}" type="number" min="0" max="10000000" step="0.0001" required value="${e(x.price)}"></td><td><input data-line="moq" aria-label="${t('Minimum quantity','最小起订量')}" type="number" min="0" max="1000000" step="0.0001" required value="${e(x.moq??0)}"></td>`:''}<td>${b('line-remove','','trash','icon-only',`aria-label="${t('Remove row','删除行')}"`)}</td></tr>`;
const lineTable=(items,quote=false)=>`<div class="table-wrap"><table class="line-editor"><thead><tr><th>${t('Product / specification','产品 / 规格')}</th><th>${t('Unit','单位')}</th><th>${t('Quantity','数量')}</th>${quote?`<th>${t('Unit price','单价')}</th><th>MOQ</th>`:''}<th></th></tr></thead><tbody id="line-rows">${items.map(x=>A.lineRow(x,quote)).join('')}</tbody></table></div>${b('line-add',t('Add product','添加产品'),'plus','small',`data-quote="${quote}"`)}`;
A.readLines=form=>[...form.querySelectorAll('#line-rows tr')].map(tr=>Object.fromEntries([...tr.querySelectorAll('[data-line]')].map(el=>[el.dataset.line,el.value.trim()])));
A.projectForm=isNew=>{A.projectDraft=isNew?E.projectDefaults():E.clone(A.p);const p=A.projectDraft;A.modal(isNew?t('Create purchasing project','创建采购项目'):t('Project requirements','项目采购要求'),`<form id="project-form"><div class="fields two">${f('name',t('Project name','项目名称'),isNew?'':p.name,'text','required maxlength="100" placeholder="e.g. Quarterly office supplies"')}<label>${t('Currency','币种')}<select name="currency">${A.currencies(p.currency)}</select></label></div>${isNew?`<p class="footnote">${t('Create a project, then import your first quotation. Its items will initialize the purchase basket. You can adjust requirements any time.','创建项目后导入首份报价，产品会自动生成采购清单。您可随时调整采购要求。')}</p>`:''}<details ${isNew?'':'open'}><summary>${t('Purchase requirements (optional)','采购要求（可选）')}</summary><div class="fields two"><label class="full">${t('Description','描述')}<textarea name="description" maxlength="2000" rows="2">${e(p.description)}</textarea></label>${f('budget',t('Budget (optional)','预算（可选）'),p.budget,'number','min="0" step="any"')}${f('baseline',t('Previous comparable cost (optional)','此前可比成本（可选）'),p.baseline,'number','min="0" step="any"')}${f('deadline',t('Required delivery within days (optional)','必须在几天内交货（可选）'),p.deadline,'number','min="0" max="3650" step="0.1"')}${check('budgetHard',t('Exclude quotations above the budget','排除超出预算的报价'),p.budgetHard)}${f('targetDays',t('Full delivery score at / before day','交期满分天数'),p.targetDays,'number','required min="0" max="3649" step="0.1"')}${f('limitDays',t('Zero delivery score at / after day','交期零分天数'),p.limitDays,'number','required min="0.1" max="3650" step="0.1"')}</div><p class="footnote">${t('Currency changes do not convert existing quotes. The baseline should cover the same basket and tax treatment; it is not realized savings. Blank deadlines mean no hard delivery constraint.','更改币种不会转换现有报价。基准须涵盖相同清单与税务处理，并非已实现节省。交期留空表示无强制交期约束。')}</p><h3>${t('Required purchase basket','所需采购清单')}</h3><p class="footnote">${t('Match purchasing SKUs exactly (including case), specifications, units and quantities. When both SKUs are blank, names must match. No fuzzy matching or unit conversion is applied. An empty basket is populated by the first quotation.','采购SKU（区分大小写）、规格、单位及数量须一致。双方SKU均为空时匹配名称，不进行模糊匹配或单位换算。首份报价可填充空白清单。')}</p>${lineTable(p.basket)}</details>${end(isNew?t('Create & add quotations','创建并添加报价'):t('Save project','保存项目'))}</form>`);};
A.quoteForm=(quote=null,reviewIndex=null)=>{A.editReview=reviewIndex!==null;A.reviewIndex=reviewIndex;A.quoteDraft=quote?E.clone(quote):{...E.quoteDefaults(A.p.currency),items:A.p.basket.map(x=>({...x,price:'',moq:0}))};const q=A.quoteDraft;if(!q.items.length)q.items=[{product:'',unit:'',qty:1,price:'',moq:0}];A.modal(t('Review quotation','审核报价'),`<form id="quote-form"><div class="fields two">${f('name',t('Supplier name','供应商名称'),q.name,'text','required maxlength="100"')}${f('reference',t('Quote reference','报价编号'),q.reference,'text','maxlength="100"')}<label>${t('Currency','币种')}<select name="currency">${A.currencies(q.currency)}</select></label>${f('source',t('Source / document','来源 / 文件'),q.source,'text','maxlength="300"')}</div><h3>${t('Quoted items','报价产品')}</h3><p class="footnote">${t('Use the same purchasing SKU and specification as the project basket only after verifying equivalence. Keep supplier part numbers in the source document or notes. Different pack sizes are not interchangeable.','确认产品等价后才可使用采购清单的相同SKU及规格。供应商自身货号请保留在来源文件或备注中。不同包装大小不能自动互换。')}</p>${A.p.basket.length?`<details><summary>${t('Check against required items','对照采购需求')}</summary><ul>${A.p.basket.map(x=>`<li>${e(E.itemLabel(x))} · ${e(x.qty)} ${e(x.unit)} ${q.items.some(y=>E.matches(x,y))?'✓':t('— no matching item','— 无匹配产品')}</li>`).join('')}</ul></details>`:''}${lineTable(q.items,true)}<h3 style="margin-top:20px">${t('Commercial terms · once per quote','商务条款 · 每份报价计一次')}</h3><div class="fields three">${f('shipping',t('Shipping before tax','税前运费'),q.shipping,'number','required min="0" step="any"')}${f('fees',t('Other fees before tax','其他税前费用'),q.fees,'number','required min="0" step="any"')}${f('discount',t('Discount value','折扣值'),q.discount,'number','required min="0" step="any"')}<label>${t('Discount type','折扣类型')}<select name="discountType"><option value="percent" ${q.discountType==='percent'?'selected':''}>${t('Percent off items','商品百分比折扣')}</option><option value="amount" ${q.discountType==='amount'?'selected':''}>${t('Fixed amount off items','商品固定金额折扣')}</option></select></label>${f('tax',t('Tax rate (%)','税率（%）'),q.tax,'number','required min="0" max="100" step="0.0001"')}${f('minOrder',t('Minimum net item value','最低税前商品金额'),q.minOrder,'number','required min="0" step="any"')}${f('days',t('Quoted delivery days','报价交货天数'),q.days,'number','min="0" max="3650" step="0.1"')}${f('validUntil',t('Valid until (optional)','有效期（可选）'),q.validUntil,'date')}${f('prepay',t('Prepayment (%) · optional','预付款（%）· 可选'),q.prepay,'number','min="0" max="100" step="0.0001"')}${f('paymentDays',t('Payment due in days · optional','付款期限（天）· 可选'),q.paymentDays,'number','min="0" max="3650" step="0.1"')}</div><div class="fields two">${check('taxIncluded',t('Item prices include tax','商品单价含税'),q.taxIncluded)}${check('taxShipping',t('Tax applies to shipping','运费计税'),q.taxShipping)}${check('taxFees',t('Tax applies to other fees','其他费用计税'),q.taxFees)}${check('allowSplit',t('Supplier confirmed partial orders and proportional discounts at these terms','供应商已确认按当前条款接受拆单及按比例折扣'),q.allowSplit)}</div><p class="footnote">${t('Enter 8 for 8%, and 0.5 for 0.5%. Blank delivery or payment fields mean unknown, not zero. Partial orders never inherit a fixed discount automatically.','8 表示 8%，0.5 表示 0.5%。交期或付款条款留空表示未知，并非零。拆单不会自动继承固定金额折扣。')}</p><details><summary>${t('Reliability evidence & notes (optional)','可靠性依据及备注（可选）')}</summary><p class="footnote">${t('Use your own records. Historical counts take priority over a supplied score. No supplier ratings are generated.','请使用自己的记录。历史计数优先于自评分数；系统不生成供应商评级。')}</p><div class="fields two">${f('historyOrders',t('Historical orders observed','历史订单数'),q.historyOrders,'number','min="1" max="1000000" step="1"')}${f('historyOnTime',t('Orders delivered on time','准时交付订单数'),q.historyOnTime,'number','min="0" max="1000000" step="1"')}<label class="full">${t('History source / period','历史来源 / 期间')}<textarea name="historySource" maxlength="2000">${e(q.historySource)}</textarea></label>${f('reliability',t('Your documented score (0–100)','您的有据评分（0–100）'),q.reliability,'number','min="0" max="100" step="0.0001"')}<label>${t('Score evidence / method','评分依据 / 方法')}<textarea name="evidence" maxlength="2000">${e(q.evidence)}</textarea></label><label class="full">${t('Procurement notes','采购备注')}<textarea name="notes" maxlength="3000">${e(q.notes)}</textarea></label></div></details><div class="notice info">${check('reviewed',t('I reviewed the products, quantities, currency, taxes and commercial terms.','我已审核产品、数量、币种、税务及商务条款。'),q.reviewed)}</div>${end(A.editReview?t('Save to import review','保存到导入审核'):t('Save quotation','保存报价'))}</form>`);};
const labels=()=>({name:t('Supplier','供应商'),reference:t('Reference','编号'),product:t('Product','产品'),sku:t('SKU / purchasing code','SKU / 采购编码'),specification:t('Specification / pack size','规格 / 包装大小'),taxFees:t('Tax fees','其他费用计税'),paymentDays:t('Payment days','付款期限'),allowSplit:t('Partial orders confirmed','已确认拆单'),unit:t('Unit','单位'),qty:t('Quantity','数量'),price:t('Unit price','单价'),moq:t('Minimum quantity','最小起订量'),shipping:t('Shipping','运费'),fees:t('Other fees','其他费用'),days:t('Delivery days','交货天数'),discount:t('Discount','折扣'),discountType:t('Discount type','折扣类型'),tax:t('Tax rate','税率'),taxShipping:t('Tax shipping','运费计税'),taxIncluded:t('Tax included','含税'),currency:t('Currency','币种'),validUntil:t('Valid until','有效期'),prepay:t('Prepayment %','预付款比例'),minOrder:t('Minimum order value','起订金额'),reliability:t('Reliability score','可靠性评分'),evidence:t('Evidence','依据')});
A.mapping=()=>{const c=A.importContext,sheet=c.book.Sheets[c.sheet];c.rows=QuoteImport.preview(c.book,c.sheet);if(c.rows.length>550)throw Error(t('This sheet exceeds 550 rows. Split large files before importing.','此工作表超过550行，请拆分文件后导入。'));if(c.header===undefined){c.header=c.rows.slice(0,20).findIndex(r=>{const m=E.autoMap(r);return (m.product>=0||m.sku>=0)&&m.qty>=0&&m.price>=0;});if(c.header<0)c.header=0;}const headers=c.rows[c.header]||[],map=E.autoMap(headers);A.modal(t('Map quotation columns','匹配报价列'),`<form id="mapping-form"><div class="notice info">${e(c.file)} · ${t('Shipping, tax and discounts apply once per quotation. Repeated terms must agree. Fill supplier names on every data row. Excel numbers retain their full stored precision.','运费、税率及折扣每份报价计一次，重复条款须一致。每个数据行都须填写供应商名称，Excel数值保留存储精度。')}</div><div class="fields two"><label>${t('Worksheet','工作表')}<select id="import-sheet">${c.book.SheetNames.map(n=>`<option ${n===c.sheet?'selected':''}>${e(n)}</option>`).join('')}</select></label><label>${t('Header row','表头行')}<select id="import-header">${c.rows.slice(0,20).map((r,i)=>`<option value="${i}" ${i===c.header?'selected':''}>${i+1} · ${e(r.slice(0,4).join(' / ').slice(0,90))}</option>`).join('')}</select></label>${f('supplier',t('Supplier when column is missing','缺少列时使用的供应商'),c.file.replace(/\.(csv|xlsx)$/i,''),'text','maxlength="100"')}<label>${t('Default currency','默认币种')}<select name="currency">${A.currencies(A.p.currency)}</select></label><label>${t('Text date order','文本日期顺序')}<select name="dateOrder"><option value="auto">${t('Detect unambiguous dates only','仅自动识别无歧义日期')}</option><option value="dmy">${t('Day / month / year','日 / 月 / 年')}</option><option value="mdy">${t('Month / day / year','月 / 日 / 年')}</option></select><small>${t('Excel date cells use the workbook date system; text dates require a four-digit year.','Excel日期单元格按工作簿日期系统解析；文本日期须使用四位年份。')}</small></label></div><div class="mapping-grid">${Object.keys(E.aliases).map(k=>`<label>${labels()[k]||k}${['qty','price'].includes(k)?' *':k==='product'?t(' (or SKU)','（或SKU）'):''}<select name="map-${k}"><option value="-1">${t('Not mapped','未匹配')}</option>${headers.map((h,i)=>`<option value="${i}" ${map[k]===i?'selected':''}>${e(h)||'Column '+(i+1)}</option>`).join('')}</select></label>`).join('')}</div><div class="notice">${check('fractions',t('Unformatted rate numbers are fractions (0.08 means 8%). Leave unchecked when 8 means 8%. Explicit % cells are always percentages.','无格式的税率/折扣数字为小数（0.08表示8%）。若8表示8%，请勿勾选。带%单元格始终按百分数处理。'),false)}</div><details><summary>${t('Preview first 5 data rows','预览前5行数据')}</summary><div class="table-wrap"><table><thead><tr>${headers.map(h=>`<th>${e(h)}</th>`).join('')}</tr></thead><tbody>${c.rows.slice(c.header+1,c.header+6).map(r=>`<tr>${headers.map((_,i)=>`<td>${e(r[i])}</td>`).join('')}</tr>`).join('')}</tbody></table></div></details>${end(t('Review quotations','审核报价'))}</form>`);};
A.importReview=()=>{A.modal(t('Review before adding','添加前审核'),`${(A.importWarnings||[]).map(w=>`<div class="notice">${e(w)}</div>`).join('')}<p class="footnote">${t('Check every quotation. Unreviewed quotes can be saved but cannot be recommended.','请核查每份报价。未审核报价可保存，但不会被推荐。')}</p><div class="table-wrap"><table><thead><tr><th>${t('Supplier','供应商')}</th><th>${t('Items','产品')}</th><th>${t('Total','总额')}</th><th>${t('Status','状态')}</th><th></th></tr></thead><tbody>${A.review.map((q,i)=>`<tr><td>${e(q.name)}</td><td>${q.items.length}</td><td>${A.money(E.totals(q).total,q.currency)}</td><td>${q.reviewed?A.badge(t('Reviewed','已审核'),'blue'):A.badge(t('Needs review','待审核'),'orange')}</td><td>${b('review-edit',t('Review & edit','审核并编辑'),'edit','small',`data-index="${i}"`)}</td></tr>`).join('')}</tbody></table></div><div class="notice info">${check('replace-import',t('Replace existing quotes with these exact supplier names; otherwise add separate quotes','替换同名供应商现有报价，否则新增独立报价'),A.importReplace)}${!A.p.basket.length?`<p>${t('The purchase basket will be initialized from the first imported supplier. Review it after import.','将使用第一家导入供应商初始化采购清单，导入后请审核。')}</p>`:''}</div><div class="dialog-actions">${b('import-map-back',t('Back to mapping','返回匹配'))}${b('import-commit',t('Add to project','添加到项目'),'check','primary')}</div>`);};
A.inspect=id=>{const r=E.analyze(A.p).rows.find(r=>r.q.id===id);if(!r)return;A.selectedSupplier=id;const q=r.q;A.modal(e(q.name),`<div class="notice ${r.reasons.length?'':'info'}">${r.reasons.length?r.reasons.map(A.reason).map(e).join(' · '):t('Eligible under current priorities','符合当前优先级要求')}</div><div class="fact-grid">${[[t('Item subtotal','商品小计'),A.money(r.subtotal,q.currency)],[t('Discount','折扣'),A.money(r.discountAmount,q.currency)],[t('Net items excluding tax','税前商品净额'),A.money(r.net,q.currency)],[t('Shipping','运费'),A.money(r.shippingAmount,q.currency)],[t('Other fees','其他费用'),A.money(r.feesAmount,q.currency)],[t('Tax','税额'),A.money(r.taxAmount,q.currency)],[t('Total landed cost','到手总成本'),A.money(r.total,q.currency)],[t('Quoted delivery','报价交期'),A.days(q.days)],[t('Prepayment exposure','预付款风险敞口'),A.money(r.prepayment,q.currency)],[t('Payment days','付款期限'),A.days(q.paymentDays)],[t('Weighted score','加权得分'),r.score?.toFixed(2)??'—'],[t('Reliability source','可靠性来源'),r.reliability?.source||t('Not provided','未提供')]].map(([k,v])=>`<div class="fact"><small>${k}</small><strong style="font-size:17px">${e(v)}</strong></div>`).join('')}</div><p class="footnote">${e(q.source)} · ${e(q.reference)}<br>${t('Item price basis:','商品价格基础：')} ${q.taxIncluded?t('Tax included','含税'):t('Tax excluded','未税')} · ${t('Tax rate','税率')} ${e(q.tax)}%</p><p class="footnote">${e(q.notes)}</p><div class="dialog-actions">${b('close',t('Close','关闭'))}${b('quote-edit',t('Edit quotation','编辑报价'),'edit','primary',`data-id="${e(id)}"`)}</div>`);};
A.fact=(id,old=false)=>{const bundle=old?A.p.aiReport?.bundle:Analyst.bundle(A.p,A.lang),fact=bundle?.facts.find(x=>x.id===id);if(!fact)return;const q=bundle.suppliers.find(x=>x.id===fact.supplierId);A.modal(e(fact.label),`<p class="footnote">${e(q?.name||bundle.project.name)}${old?' · '+t('Saved report snapshot','已保存报告快照'):''}</p><div class="report-hero"><h2>${fact.value===null?t('Not provided','未提供'):e(fact.unit in E.CURRENCIES?A.money(fact.value,fact.unit):String(fact.value))} ${fact.unit in E.CURRENCIES?'':e(fact.unit)}</h2></div><p class="footnote">${t('Fact ID','事实编号')}: ${e(id)}<br>${t('Snapshot','快照')}: ${e(bundle.generatedAt)}</p><div class="dialog-actions">${b('close',t('Close','关闭'))}${!old&&q?b('inspect',t('Inspect supplier data','查看供应商数据'),'analysis','primary',`data-id="${e(q.id)}"`):b('view-matrix',t('Open quote matrix','打开报价矩阵'),'analysis','primary')}</div>`);};
A.decisionForm=()=>{const a=E.analyze(A.p),selected=Analyst.report(A.p,A.lang).chosen?.q.id;if(!a.eligible.length)throw Error(t('There are no eligible suppliers to record. Resolve quotation gaps first.','暂无合格供应商，请先解决报价问题。'));A.modal(t('Record purchasing decision','记录采购决策'),`<form id="decision-form"><label>${t('Selected supplier','所选供应商')}<select name="supplier">${a.ranked.map(r=>`<option value="${e(r.q.id)}" ${r.q.id===selected?"selected":""}>${e(r.q.name)} · ${A.money(r.total)} · ${r.score?.toFixed(1)??'—'}/100</option>`).join('')}</select></label><label style="margin-top:16px">${t('Business reason and conditions before ordering','业务理由及下单前条件')}<textarea name="reason" rows="4" maxlength="3000" required placeholder="${t('Explain the trade-off and any terms that still need written confirmation.','说明取舍以及仍需书面确认的条款。')}"></textarea></label><p class="footnote">${t('This saves a dated snapshot, not a purchase order or approval. It will be marked stale when relevant data or the date changes.','这会保存带日期的快照，并非采购订单或审批。相关数据或日期变更后会标记为过时。')}</p>${end(t('Record decision','记录决策'))}</form>`);};
A.aiPreview=()=>{if(A.aiBusy)return;Analyst.validateConfig(A.workspace.api);A.pendingAI={projectId:A.p.id,bundle:Analyst.bundle(A.p,A.lang),focus:A.$('#ai-focus')?.value||'',config:E.clone(A.workspace.api),connectionRevision:A.connectionRevision};const data=A.pendingAI;A.modal(t('Review the data being sent','审核将发送的数据'),`<div class="notice">${t('Destination','目标接口')}: <b>${e(data.config.endpoint)}</b><br>${t('Model','模型')}: ${e(data.config.model)}<br>${t('This sends supplier names, quotation facts, evidence sources, notes and your focus to this provider. Provider charges and data policies apply.','将向此服务商发送供应商名称、报价事实、依据来源、备注及关注点。适用服务商费用及数据政策。')}</div><details><summary>${t('View the complete snapshot and focus','查看完整快照及关注点')}</summary><pre class="json-preview">${e(JSON.stringify({focus:data.focus,snapshot:data.bundle},null,2))}</pre></details><label class="check" style="margin-top:18px"><input id="ai-consent" type="checkbox">${t('Send this snapshot to the endpoint shown above.','将此快照发送到上述接口。')}</label><div class="dialog-actions">${b('close',t('Cancel','取消'))}${b('ai-send',t('Send & generate','发送并生成'),'spark','primary','disabled')}</div>`);};
A.exportDialog=()=>A.modal(t('Export decision pack','导出决策包'),`<p class="footnote">${t('Export the current project with its calculation rules, evidence and recommendations. A workspace backup additionally includes every project.','导出当前项目及其计算规则、依据和建议。工作区备份另含全部项目。')}</p><div class="export-options">${b('export-xlsx',t('Excel workbook','Excel 工作簿'),'download')}${b('export-csv',t('Comparison CSV','比较 CSV'),'download')}${b('export-html',t('Readable decision report','可读决策报告'),'quote')}${b('backup',t('Full workspace backup','完整工作区备份'),'download')}</div>`);
A.check=check;
})();
